def _check(ranges):
    """Raise ValueError if any tuple is not a valid closed integer range."""
    for r in ranges:
        if len(r) != 2:
            raise ValueError("a range is a pair of ints")
        start, end = r[0], r[1]
        if not (isinstance(start, int) and isinstance(end, int)):
            raise ValueError("a range endpoints must be ints")
        if start > end:
            raise ValueError("start > end is not a range")


def _copy(ranges):
    """Return a list of tuple copies, preserving the caller's list untouched."""
    return [tuple(r) for r in ranges]


def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges. See TASK.md."""
    _check(ranges)
    items = sorted(tuple(r) for r in ranges)
    out = []
    for start, end in items:
        if not out:
            out.append([start, end])
            continue
        s0, e0 = out[-1][0], out[-1][1]
        # neighboring means e0 + 1 == start (e.g. (1,2),(3,4) -> (1,4))
        if start <= e0 + 1:
            if end > e0:
                out[-1][1] = end
        else:
            out.append([start, end])
    return [tuple(r) for r in out]


def subtract(ranges, holes):
    """The integers in `ranges` that are not in `holes`, as merged ranges."""
    _check(ranges)
    _check(holes)
    merged_ranges = merge(ranges)
    merged_holes = merge(holes)
    result = []
    for r_start, r_end in merged_ranges:
        cur = r_start
        for h_start, h_end in merged_holes:
            if h_start > r_end or h_end < r_start:
                continue
            # hole intersects this range; cut [cur, ...] into pieces
            if h_start > cur:
                result.append((cur, h_start - 1))
            cur = max(cur, h_end + 1)
            if cur > r_end:
                break
        if cur <= r_end:
            result.append((cur, r_end))
    return result


def count(ranges):
    """How many distinct integers the ranges hold."""
    _check(ranges)
    merged = merge(ranges)
    return sum(end - start + 1 for start, end in merged)
